<?php require_once __DIR__.'/../includes/layout.php'; require_once __DIR__.'/../includes/otp.php'; require_once __DIR__.'/../includes/validation.php'; $email=$_SESSION['reset_email']??''; $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $errs=password_errors($_POST['password']??''); if($_POST['password']!==($_POST['confirm_password']??''))$errs[]='Passwords do not match.'; if(!$errs && verify_otp_code($_POST['email'],'password_reset',$_POST['otp'])){db()->prepare('UPDATE users SET password_hash=? WHERE email=?')->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['email']]); audit('password_reset','users',null,['email'=>$_POST['email']]); $msg='Password changed successfully.';} else $msg=$errs?implode(' ',$errs):'Invalid OTP.';} auth_header('Reset Password'); ?><h2 class="brand">Set new password</h2><?php if($msg):?><div class="alert alert-info"><?=e($msg)?></div><?php endif;?><form method="post" class="vstack gap-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input name="email" class="form-control" value="<?=e($email)?>" required><input name="otp" class="form-control" placeholder="OTP" required><input type="password" name="password" class="form-control" placeholder="New password" data-strength="#strength"><div class="progress"><div id="strength" class="progress-bar"></div></div><input type="password" name="confirm_password" class="form-control" placeholder="Confirm password"><button class="btn btn-premium">Change Password</button></form><?php auth_footer(); ?>
